
/* ============================================================
   SV-SECTION: Ứng viên nổi bật — lazy-load qua API
============================================================ */
(function () {
  var sliderWrap = document.getElementById('svSliderWrap');
  var track      = document.getElementById('svTrack');
  var dotsWrap   = document.getElementById('svDotsWrap');
  var btnPrev    = document.getElementById('svPrev');
  var btnNext    = document.getElementById('svNext');
  var pagination = document.getElementById('svPagination');
  var timerFill  = document.getElementById('svTimerFill');
  var timerText  = document.getElementById('svTimerText');
  if (!sliderWrap || !track) return;

  var totalPages = Math.max(1, parseInt(sliderWrap.getAttribute('data-total-pages') || '1', 10));
  var apiUrl     = sliderWrap.getAttribute('data-api-url') || '/api/homeFeaturedCandidates';
  var DURATION   = 15000;
  var FADE_MS    = 250;
  var currentPage   = 0;
  var isLoading     = false;
  var timerInterval = null;
  var timerStart    = null;

  var grid = track.querySelector('.sv-grid');
  var pageCache = {};
  if (grid) { pageCache[0] = grid.innerHTML; }

  function setGridWidth() {
    if (grid) { grid.style.width = sliderWrap.offsetWidth + 'px'; }
  }
  setGridWidth();
  window.addEventListener('resize', setGridWidth);

  if (totalPages <= 1) {
    if (pagination) pagination.style.display = 'none';
    return;
  }

  function buildDots(total) {
    if (!dotsWrap) return;
    dotsWrap.innerHTML = '';
    for (var i = 0; i < total; i++) {
      (function (idx) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'sv-dot' + (idx === 0 ? ' active' : '');
        btn.setAttribute('aria-label', 'Trang ' + (idx + 1));
        btn.addEventListener('click', function () { svGoTo(idx); });
        dotsWrap.appendChild(btn);
      })(i);
    }
  }
  buildDots(totalPages);

  function updateDots(page) {
    if (!dotsWrap) return;
    dotsWrap.querySelectorAll('.sv-dot').forEach(function (d, i) {
      d.classList.toggle('active', i === page);
    });
  }

  function updateNav() {
    if (btnPrev) btnPrev.disabled = currentPage <= 0;
    if (btnNext) btnNext.disabled = currentPage >= totalPages - 1;
  }
  updateNav();

  function skeletonCard() {
    var sk = 'background:linear-gradient(90deg,#e8edf3 25%,#f5f7fa 50%,#e8edf3 75%);background-size:200% 100%;animation:svSkeletonPulse 1.4s ease-in-out infinite;border-radius:';
    return '<div class="sv-card sv-card-skeleton">'
      + '<div class="sv-avatar-wrap" style="border:none;' + sk + '50%"></div>'
      + '<div style="width:65%;height:13px;margin:10px auto 6px;' + sk + '6px"></div>'
      + '<div style="width:45%;height:11px;margin:0 auto 10px;' + sk + '6px"></div>'
      + '<div style="width:58%;height:22px;margin:0 auto;' + sk + '20px"></div>'
      + '</div>';
  }
  function showSkeleton() {
    if (!grid) return;
    var html = '';
    for (var i = 0; i < 12; i++) { html += skeletonCard(); }
    grid.innerHTML = html;
  }

  function fetchPage(page, callback) {
    if (pageCache[page] !== undefined) { callback(null, pageCache[page]); return; }
    fetch(apiUrl + '?page=' + (page + 1))
      .then(function (r) { return r.json(); })
      .then(function (data) {
        if (data && data.status === 200) {
          var tp = parseInt(data.total_pages, 10);
          if (!isNaN(tp) && tp > 0 && tp !== totalPages) {
            totalPages = tp;
            buildDots(totalPages);
            updateNav();
          }
          pageCache[page] = data.html || '';
          callback(null, pageCache[page]);
        } else { callback('api-error'); }
      })
      .catch(function (err) { callback(err); });
  }

  window.svGoTo = function (page) {
    if (isLoading || page === currentPage || page < 0 || page >= totalPages) return;
    isLoading = true;
    if (!grid) { isLoading = false; return; }
    grid.style.opacity = '0';
    setTimeout(function () {
      showSkeleton();
      grid.style.opacity = '1';
      fetchPage(page, function (err, html) {
        isLoading = false;
        if (err) { grid.innerHTML = pageCache[currentPage] || ''; return; }
        currentPage = page;
        grid.style.opacity = '0';
        grid.innerHTML = html;
        setTimeout(function () {
          grid.style.opacity = '1';
          updateDots(currentPage);
          updateNav();
        }, 50);
      });
    }, FADE_MS);
    startTimer();
  };

  if (btnPrev) {
    btnPrev.addEventListener('click', function () {
      svGoTo(currentPage > 0 ? currentPage - 1 : 0);
    });
  }
  if (btnNext) {
    btnNext.addEventListener('click', function () {
      svGoTo(currentPage < totalPages - 1 ? currentPage + 1 : totalPages - 1);
    });
  }

  var touchStartX = 0;
  sliderWrap.addEventListener('touchstart', function (e) {
    touchStartX = e.changedTouches[0].clientX;
  }, { passive: true });
  sliderWrap.addEventListener('touchend', function (e) {
    var diff = touchStartX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) {
      svGoTo(diff > 0
        ? (currentPage < totalPages - 1 ? currentPage + 1 : currentPage)
        : (currentPage > 0 ? currentPage - 1 : currentPage));
    }
  }, { passive: true });

  function resetTimerBar() {
    timerStart = Date.now();
    if (timerFill) {
      timerFill.style.transition = 'none';
      timerFill.style.width = '0%';
      setTimeout(function () { if (timerFill) timerFill.style.transition = ''; }, 50);
    }
  }
  function startTimer() {
    clearInterval(timerInterval);
    resetTimerBar();
    timerInterval = setInterval(function () {
      var elapsed = Date.now() - timerStart;
      var pct = Math.min((elapsed / DURATION) * 100, 100);
      if (timerFill) timerFill.style.width = pct + '%';
      if (timerText) timerText.textContent = Math.max(0, Math.ceil((DURATION - elapsed) / 1000)) + 's';
      if (elapsed >= DURATION) {
        svGoTo((currentPage + 1) % totalPages);
        resetTimerBar();
      }
    }, 100);
  }
  startTimer();
})();

/* ============================================================
   JOBS-SECTION: Việc làm nổi bật — client-side pagination
============================================================ */
(function () {
  var track = document.getElementById('jobsTrack');
  var grid = document.getElementById('jobsGrid');
  var dotsWrap = document.getElementById('jobsDots');
  var timerFill = document.getElementById('jobsTimerFill');
  var timerText = document.getElementById('jobsTimerText');
  var btnPrev = document.getElementById('jobsPrev');
  var btnNext = document.getElementById('jobsNext');
  var sliderWrap = document.getElementById('jobsSliderWrap');
  if (!track || !grid || !dotsWrap) return;

  var PER_PAGE = 12;
  var DURATION = 10000;
  var cards = Array.prototype.slice.call(grid.querySelectorAll('.job-card'));
  var totalPages = Math.max(1, Math.ceil(cards.length / PER_PAGE));
  var currentPage = 0;
  var timerInterval = null;
  var timerStart = null;
  var isAnimating = false;

  if (totalPages <= 1) {
    document.getElementById('jobsPagination').style.display = 'none';
    return;
  }

  track.innerHTML = '';
  for (var p = 0; p < totalPages; p++) {
    var page = document.createElement('div');
    page.className = 'jobs-page';
    var pageGrid = document.createElement('div');
    pageGrid.className = 'jobs-grid';
    cards.slice(p * PER_PAGE, (p + 1) * PER_PAGE).forEach(function (card) {
      pageGrid.appendChild(card);
    });
    page.appendChild(pageGrid);
    track.appendChild(page);
  }

  var dots = [];
  for (var d = 0; d < totalPages; d++) {
    var dot = document.createElement('button');
    dot.type = 'button';
    dot.className = 'jobs-dot' + (d === 0 ? ' active' : '');
    dot.setAttribute('aria-label', 'Trang ' + (d + 1));
    dot.dataset.page = d;
    dot.addEventListener('click', function () {
      jobsGoTo(parseInt(this.dataset.page, 10));
    });
    dotsWrap.appendChild(dot);
    dots.push(dot);
  }

  function slideTo(page) {
    if (isAnimating) return;
    isAnimating = true;
    track.style.transition = 'transform 0.55s cubic-bezier(0.4,0,0.2,1)';
    track.style.transform = 'translateX(-' + (page * 100) + '%)';
    dots.forEach(function (dot, i) {
      dot.classList.toggle('active', i === page);
    });
    setTimeout(function () { isAnimating = false; }, 580);
  }

  function resetTimerBar() {
    timerStart = Date.now();
    if (timerFill) {
      timerFill.style.transition = 'none';
      timerFill.style.width = '0%';
      setTimeout(function () {
        if (timerFill) timerFill.style.transition = '';
      }, 50);
    }
  }

  function startTimer() {
    clearInterval(timerInterval);
    resetTimerBar();
    timerInterval = setInterval(function () {
      var elapsed = Date.now() - timerStart;
      var pct = Math.min((elapsed / DURATION) * 100, 100);
      if (timerFill) timerFill.style.width = pct + '%';
      if (timerText) timerText.textContent = Math.max(0, Math.ceil((DURATION - elapsed) / 1000)) + 's';
      if (elapsed >= DURATION) {
        currentPage = (currentPage + 1) % totalPages;
        slideTo(currentPage);
        resetTimerBar();
      }
    }, 100);
  }

  window.jobsGoTo = function (page) {
    if (page === currentPage || page < 0 || page >= totalPages) return;
    currentPage = page;
    slideTo(currentPage);
    startTimer();
  };

  if (btnPrev) {
    btnPrev.addEventListener('click', function () {
      jobsGoTo((currentPage - 1 + totalPages) % totalPages);
    });
  }
  if (btnNext) {
    btnNext.addEventListener('click', function () {
      jobsGoTo((currentPage + 1) % totalPages);
    });
  }

  var touchStartX = 0;
  if (sliderWrap) {
    sliderWrap.addEventListener('touchstart', function (e) {
      touchStartX = e.changedTouches[0].clientX;
    }, { passive: true });
    sliderWrap.addEventListener('touchend', function (e) {
      var diff = touchStartX - e.changedTouches[0].clientX;
      if (Math.abs(diff) > 50) {
        jobsGoTo(diff > 0 ? (currentPage + 1) % totalPages : (currentPage - 1 + totalPages) % totalPages);
      }
    }, { passive: true });
  }

  track.style.transform = 'translateX(0%)';
  startTimer();
})();

(function () {
  var LOCATIONS = [
    'Toàn quốc', 'Hà Nội', 'TP. Hồ Chí Minh', 'Đà Nẵng', 'Bình Dương', 'Đồng Nai',
    'Cần Thơ', 'Hải Phòng', 'An Giang', 'Bà Rịa - Vũng Tàu', 'Lâm Đồng', 'Khánh Hòa',
    'Long An', 'Bắc Ninh', 'Hưng Yên', 'Nghệ An', 'Thanh Hóa', 'Quảng Nam', 'Bình Định',
    'Kiên Giang', 'Đồng Tháp', 'Vĩnh Phúc', 'Thái Nguyên', 'Quảng Ninh'
  ];

  var btn = document.getElementById('searchLocationBtn');
  var dropdown = document.getElementById('locationDropdown');
  var searchWrap = document.getElementById('heroSearchWrap');
  var heroSlider = document.getElementById('heroSlider');
  var searchInput = document.getElementById('locationSearchInput');
  var listEl = document.getElementById('locationList');
  var emptyEl = document.getElementById('locationEmpty');
  var labelEl = document.getElementById('searchLocationLabel');
  if (!btn || !dropdown || !listEl || !labelEl) return;
  if (btn.getAttribute('data-location-initialized') === 'true') return;

  var selected = 'Toàn quốc';

  function normalize(str) {
    return str
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd')
      .replace(/Đ/g, 'D');
  }

  function renderList(filter) {
    var q = normalize((filter || '').trim());
    var items = LOCATIONS.filter(function (name) {
      return !q || normalize(name).indexOf(q) !== -1;
    });
    listEl.innerHTML = '';
    emptyEl.hidden = items.length > 0;
    items.forEach(function (name) {
      var li = document.createElement('li');
      var button = document.createElement('button');
      button.type = 'button';
      button.innerHTML = '<i class="ti ti-map-pin"></i> ' + name;
      if (name === selected) button.classList.add('active');
      button.addEventListener('click', function () {
        selected = name;
        labelEl.textContent = name;
        closeDropdown();
      });
      li.appendChild(button);
      listEl.appendChild(li);
    });
  }

  function resetDropdownPosition() {
    dropdown.style.position = '';
    dropdown.style.top = '';
    dropdown.style.bottom = '';
    dropdown.style.left = '';
    dropdown.style.right = '';
    dropdown.style.width = '';
  }
  function positionDropdown() { resetDropdownPosition(); }

  function openDropdown() {
    dropdown.classList.add('open');
    btn.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
    dropdown.setAttribute('aria-hidden', 'false');
    if (searchWrap) searchWrap.classList.add('location-open');
    if (heroSlider) heroSlider.classList.add('location-dropdown-open');
    searchInput.value = '';
    renderList('');
    positionDropdown();
    setTimeout(function () { searchInput.focus(); }, 0);
  }

  function closeDropdown() {
    dropdown.classList.remove('open');
    btn.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
    dropdown.setAttribute('aria-hidden', 'true');
    if (searchWrap) searchWrap.classList.remove('location-open');
    if (heroSlider) heroSlider.classList.remove('location-dropdown-open');
    resetDropdownPosition();
  }

  function toggleDropdown(e) {
    e.stopPropagation();
    if (dropdown.classList.contains('open')) closeDropdown();
    else openDropdown();
  }

  btn.addEventListener('click', toggleDropdown);
  btn.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleDropdown(e); }
  });
  searchInput.addEventListener('input', function () { renderList(searchInput.value); });
  searchInput.addEventListener('click', function (e) { e.stopPropagation(); });
  dropdown.addEventListener('click', function (e) { e.stopPropagation(); });
  document.addEventListener('click', function () {
    if (dropdown.classList.contains('open')) closeDropdown();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && dropdown.classList.contains('open')) closeDropdown();
  });
  window.addEventListener('resize', function () {
    if (dropdown.classList.contains('open')) positionDropdown();
    else resetDropdownPosition();
  });
  renderList('');
})();
